package main

import (
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

type OrderRec struct { // 01 ORDER-REC, 15 bytes
	OrId    string          // PIC X(5) @0 len=5
	OrStat  string          // PIC X(1) @5 len=1
	OrQty   int64           // PIC 9(3) @6 len=3
	OrPrice decimal.Decimal // PIC 9(4)V99 @9 len=6
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N"                   // PIC X len=1 = "N"
var WsTotal decimal.Decimal // PIC 9(8)V99 len=10 = 0
var WsGrand decimal.Decimal // PIC 9(10)V99 len=12 = 0
var WsNewCount int64        // PIC 99 len=2 = 0
var WsShipCount int64       // PIC 99 len=2 = 0
var WsCancelCount int64     // PIC 99 len=2 = 0
var WsInvalid int64         // PIC 99 len=2 = 0
var WsBadQty int64          // PIC 99 len=2 = 0
var WsQtyEd string          // PIC ZZ9 len=3
var WsPriceEd string        // PIC Z,ZZ9.99 len=8
var WsTotalEd string        // PIC ZZ,ZZZ,ZZ9.99 len=13
var WsGrandEd string        // PIC Z,ZZZ,ZZZ,ZZ9.99 len=16

var curRec OrderRec
var orderLines []string
var orderIndex int

func main() {
	WsEofFlag = "N"
	WsTotal = decimal.NewFromInt(0)
	WsGrand = decimal.NewFromInt(0)
	WsNewCount = 0
	WsShipCount = 0
	WsCancelCount = 0
	WsInvalid = 0
	WsBadQty = 0
	mainPara()
}

func mainPara() {
	openOrderFile()
	readPara()
	for !inputDone() {
		processPara()
	}
	closeOrderFile()
	summaryPara()
}

func readPara() {
	if orderIndex >= len(orderLines) {
		WsEofFlag = "Y"
		return
	}
	line := orderLines[orderIndex]
	orderIndex++
	if len(line) < 15 {
		line = line + strings.Repeat(" ", 15-len(line))
	} else if len(line) > 15 {
		line = line[:15]
	}
	curRec.OrId = line[0:5]
	curRec.OrStat = line[5:6]
	qtyStr := line[6:9]
	priceStr := line[9:15]

	qtyTrim := strings.TrimSpace(qtyStr)
	var q int64 = 0
	if qtyTrim != "" {
		if v, err := strconv.ParseInt(qtyTrim, 10, 64); err == nil {
			q = v
		} else {
			// if contains non-digit treat as 0
			q = 0
		}
	}
	curRec.OrQty = q

	priceTrim := strings.TrimSpace(priceStr)
	var p decimal.Decimal = decimal.NewFromInt(0)
	if priceTrim != "" {
		isDigits := true
		for _, ch := range priceTrim {
			if ch < '0' || ch > '9' {
				isDigits = false
				break
			}
		}
		if isDigits {
			if n, err := strconv.ParseInt(priceTrim, 10, 64); err == nil {
				p = decimal.New(n, -2)
			}
		}
	}
	curRec.OrPrice = p
}

func processPara() {
	WsTotal = decimal.NewFromInt(0)
	if curRec.OrQty == 0 {
		WsBadQty = fitCount(WsBadQty + 1)
		fmt.Printf("%s%s\n", curRec.OrId, " BAD QTY")
	} else if curRec.OrStat == "N" {
		raw := decimal.NewFromInt(curRec.OrQty).Mul(curRec.OrPrice)
		rawTrunc := raw.Truncate(2)
		WsTotal = fitDecimal(rawTrunc, 8, 2)
		WsNewCount = fitCount(WsNewCount + 1)
		showPara()
	} else if curRec.OrStat == "S" {
		factor, _ := decimal.NewFromString("1.05")
		raw := decimal.NewFromInt(curRec.OrQty).Mul(curRec.OrPrice).Mul(factor)
		rawRounded := raw.Round(2)
		WsTotal = fitDecimal(rawRounded, 8, 2)
		WsShipCount = fitCount(WsShipCount + 1)
		showPara()
	} else if curRec.OrStat == "C" {
		WsCancelCount = fitCount(WsCancelCount + 1)
		showPara()
	} else {
		WsInvalid = fitCount(WsInvalid + 1)
		fmt.Printf("%s%s%s\n", curRec.OrId, " BAD STATUS ", curRec.OrStat)
	}
	WsGrand = WsGrand.Add(WsTotal)
	WsGrand = fitDecimal(WsGrand, 10, 2)
	readPara()
}

func showPara() {
	WsQtyEd = formatEdited(decimal.NewFromInt(curRec.OrQty), "ZZ9")
	WsPriceEd = formatEdited(curRec.OrPrice, "Z,ZZ9.99")
	WsTotalEd = formatEdited(WsTotal, "ZZ,ZZZ,ZZ9.99")
	fmt.Printf("%s %s %s %s %s\n", curRec.OrId, curRec.OrStat, WsQtyEd, WsPriceEd, WsTotalEd)
}

func summaryPara() {
	WsGrandEd = formatEdited(WsGrand, "Z,ZZZ,ZZZ,ZZ9.99")
	fmt.Printf("NEW: %s SHIPPED: %s CANCELLED: %s\n", formatPIC99(WsNewCount), formatPIC99(WsShipCount), formatPIC99(WsCancelCount))
	fmt.Printf("INVALID: %s BAD QTY: %s\n", formatPIC99(WsInvalid), formatPIC99(WsBadQty))
	fmt.Printf("GRAND TOTAL: %s\n", WsGrandEd)
}

func openOrderFile() {
	data, err := os.ReadFile("input.dat")
	if err != nil {
		if os.IsNotExist(err) {
			orderLines = []string{}
			orderIndex = 0
			return
		}
		fmt.Fprintf(os.Stderr, "open error: %v\n", err)
		os.Exit(1)
	}
	if len(data) == 0 {
		orderLines = []string{}
		orderIndex = 0
		return
	}
	content := string(data)
	rawLines := strings.Split(content, "\n")
	if strings.HasSuffix(content, "\n") {
		if len(rawLines) > 0 && rawLines[len(rawLines)-1] == "" {
			rawLines = rawLines[:len(rawLines)-1]
		}
	}
	for i, ln := range rawLines {
		if len(ln) > 0 && ln[len(ln)-1] == '\r' {
			rawLines[i] = ln[:len(ln)-1]
		}
	}
	orderLines = rawLines
	orderIndex = 0
}

func closeOrderFile() {}

func inputDone() bool { return WsEofFlag == "Y" }

func int64Pow(b, e int) int64 {
	var r int64 = 1
	for i := 0; i < e; i++ {
		r *= int64(b)
	}
	return r
}

func fitCount(v int64) int64 {
	pow := int64Pow(10, 2)
	return v % pow
}

func fitDecimal(v decimal.Decimal, intDigits int, scale int) decimal.Decimal {
	powTotal := int64Pow(10, intDigits+scale)
	shifted := v.Shift(int32(scale)).Truncate(0)
	units := shifted.IntPart()
	mod := units % powTotal
	return decimal.New(mod, int32(-scale))
}

func formatPIC99(v int64) string {
	m := v % 100
	if m < 0 {
		m = -m
	}
	return fmt.Sprintf("%02d", m)
}

func formatEdited(val decimal.Decimal, pic string) string {
	dot := strings.Index(pic, ".")
	intPic := pic
	scale := 0
	if dot != -1 {
		intPic = pic[:dot]
		for _, ch := range pic[dot+1:] {
			if ch == '9' || ch == 'Z' {
				scale++
			}
		}
	}
	intDigits := 0
	for _, ch := range intPic {
		if ch == '9' || ch == 'Z' {
			intDigits++
		}
	}
	abs := val.Abs()
	// truncate to scale for display
	absTrunc := abs.Truncate(int32(scale))
	powScaleInt := int64Pow(10, scale)
	powIntDigitsInt := int64Pow(10, intDigits)

	// total units
	var powScaleDec decimal.Decimal
	if scale > 0 {
		powScaleDec = decimal.NewFromInt(1).Shift(int32(scale))
	} else {
		powScaleDec = decimal.NewFromInt(1)
	}
	totalUnits := absTrunc.Mul(powScaleDec).Truncate(0).IntPart()
	intPartInt := totalUnits
	fracPartInt := int64(0)
	if scale > 0 {
		intPartInt = totalUnits / powScaleInt
		fracPartInt = totalUnits % powScaleInt
		if fracPartInt < 0 {
			fracPartInt = -fracPartInt
		}
	}
	intPartMod := intPartInt % powIntDigitsInt
	if intPartMod < 0 {
		intPartMod = -intPartMod
	}
	digitsPadded := fmt.Sprintf("%0*d", intDigits, intPartMod)
	fracStr := ""
	if scale > 0 {
		fracStr = fmt.Sprintf("%0*d", scale, fracPartInt)
	}

	// build integer part with suppression
	outRunes := make([]rune, len(intPic))
	digitChars := []rune(digitsPadded)
	dPos := 0
	for i, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			outRunes[i] = digitChars[dPos]
			dPos++
		} else {
			outRunes[i] = ch
		}
	}
	stillSuppressed := true
	for i, picCh := range intPic {
		c := outRunes[i]
		switch picCh {
		case 'Z':
			if stillSuppressed {
				if c == '0' {
					outRunes[i] = ' '
				} else {
					stillSuppressed = false
				}
			}
		case '9':
			if c != '0' {
				stillSuppressed = false
			}
			// keep digit
		case ',':
			if stillSuppressed {
				outRunes[i] = ' '
			} else {
				outRunes[i] = ','
			}
		}
	}
	intStr := string(outRunes)
	if scale > 0 {
		return intStr + "." + fracStr
	}
	return intStr
}
